// Generate the Rust source-only furniture definition index. No edit authority.
import {readFileSync,writeFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
export const sourcePath=new URL('../public/inventory-ui/furniture-customization-v3.0.1.json',import.meta.url);
export const rustPath=new URL('../core/src/furniture_source.rs',import.meta.url);
export function generateFurnitureSource(d){
 const sets=new Map(d.sets.map(([id,,indices])=>[id,indices]));
 const lines=[
 '// @generated by scripts/generate-furniture-source.mjs; do not hand-edit.',
 '// Native v3.0.1 source definitions only. Membership is not an ownership or mutation grant.',
 '#[derive(Debug,Clone,Copy,PartialEq,Eq)]',
 'pub struct FurnitureSlotSource {pub slot:u8,pub default_index:i32,pub allowed:&\'static [i32]}',
 '#[derive(Debug,Clone,Copy,PartialEq,Eq)]',
 'pub struct FurnitureItemSource {pub item_id:i32,pub is_home_layout:bool,pub slots:&\'static [FurnitureSlotSource]}',
 'pub const ITEMS:&[FurnitureItemSource]=&['
 ];
 for(const [id,,,kind,slots] of d.items){
  const fields=slots.map(([slot,,def,refs])=>{
   const allowed=[...new Set(refs.flatMap(ref=>{if(!sets.has(ref))throw Error('Unresolved set');return sets.get(ref)}))];
   return 'FurnitureSlotSource{slot:'+slot+',default_index:'+def+',allowed:&['+allowed.join(',')+']}';
  });
  lines.push(' FurnitureItemSource{item_id:'+id+',is_home_layout:'+(kind===1)+',slots:&['+fields.join(',')+']},');
 }
 lines.push('];','pub const MATERIAL_UNLOCK_ITEMS:&[(i32,i32)]=&[');
 for(const [index,,,,unlock] of d.materials)if(unlock!==null)lines.push(' ('+index+','+unlock+'),');
 lines.push('];',
  'pub fn item(id:i32)->Option<&\'static FurnitureItemSource>{ITEMS.binary_search_by_key(&id,|x|x.item_id).ok().map(|i|&ITEMS[i])}',
  'pub fn slot(id:i32,slot:u8)->Option<&\'static FurnitureSlotSource>{item(id)?.slots.iter().find(|x|x.slot==slot)}',
  'pub fn material_unlock_item(index:i32)->Option<i32>{MATERIAL_UNLOCK_ITEMS.iter().find(|x|x.0==index).map(|x|x.1)}',
  '');
 return lines.join('\n');
}
if(process.argv[1]===fileURLToPath(import.meta.url)){
 const s=generateFurnitureSource(JSON.parse(readFileSync(sourcePath)));
 if(process.argv.includes('--check')){
  if(readFileSync(rustPath,'utf8')!==s)throw Error('Furniture source index is stale');
 }else writeFileSync(rustPath,s);
}
